const body = $input.item.json;

const nome = body['Nome completo'] || '';
const email = body['Email'] || '';
const empresa = body['Empresa'] || '';
const cargo = body['Cargo'] || '';
const site = body['Site da empresa'] || '';

if (!nome || !empresa) {
  throw new Error('Nome e empresa são obrigatórios');
}

return {
  json: { nome, email, empresa, cargo, site }
};

const serperData = $input.item.json;
const lead = $('Extrai Dados do Lead').item.json;

const organicResults = serperData.organic || [];
const knowledgeGraph = serperData.knowledgeGraph || {};

const resumoBusca = organicResults
  .slice(0, 4)
  .map(r => `- ${r.title}: ${r.snippet}`)
  .join('\n');

const contextoEmpresa = knowledgeGraph.description || '';

const promptPesquisa = `Com base nas informações abaixo sobre a empresa "${lead.empresa}", extraia e estruture os seguintes dados em JSON:

1. setor (ex: SaaS, E-commerce, Fintech, Indústria, Serviços, Saúde, Educação, etc)
2. porte_estimado (Startup, Pequena, Média, Grande, Enterprise) — baseie-se nas informações disponíveis
3. tecnologias_usadas (array de tecnologias mencionadas, se houver)
4. momento_atual (crescimento, expansão, desafio, estável — baseado em notícias)
5. resumo_empresa (2 frases sobre o que a empresa faz)
6. pontos_de_dor_possiveis (array com 2-3 possíveis dores baseadas no setor e porte)

Informações encontradas:
Empresa: ${lead.empresa}
Site: ${lead.site}
Cargo do contato: ${lead.cargo}
Descrição: ${contextoEmpresa}

Resultados de busca:
${resumoBusca}

Retorne APENAS um JSON válido, sem explicações.`;

const messages = [
  {
    role: 'system',
    content: 'Você é um especialista em inteligência de mercado B2B. Analise informações de empresas e retorne APENAS JSON válido, sem markdown, sem explicações.'
  },
  {
    role: 'user',
    content: promptPesquisa
  }
];

const bodyString = JSON.stringify({
  model: 'llama-3.3-70b-versatile',
  messages: messages,
  temperature: 0.3,
  max_tokens: 800
});

return {
  json: {
    lead,
    promptPesquisa,
    resumoBusca,
    contextoEmpresa,
    messages,
    bodyString
  }
};

const groqResponse = $input.item.json;
const perfilBruto = groqResponse.choices[0].message.content;
const lead = $('Monta Prompt — Agente Pesquisador').item.json.lead;

let perfil = {};
try {
  const clean = perfilBruto.replace(/```json|```/g, '').trim();
  perfil = JSON.parse(clean);
} catch(e) {
  perfil = { setor: 'Desconhecido', porte_estimado: 'Desconhecido', tecnologias_usadas: [], momento_atual: 'estável', resumo_empresa: perfilBruto.slice(0, 200), pontos_de_dor_possiveis: [] };
}

const promptScore = `Você é um especialista em qualificação de leads B2B. Avalie o lead abaixo com base nos critérios do ICP e gere um score de 0 a 100.\n\nCRITÉRIOS:\n- Setor (SaaS/Tech/Fintech = 25pts | E-commerce/Serviços = 20pts | Outros = 10pts)\n- Porte (Enterprise = 25pts | Grande = 20pts | Média = 15pts | Pequena = 10pts | Startup = 5pts)\n- Cargo (C-Level/Diretor/VP = 20pts | Gerente = 15pts | Analista = 5pts)\n- Momento (Crescimento/Expansão = 15pts | Estável = 10pts | Desafio = 5pts)\n- Tecnologias modernas = bônus até 15pts\n\nDADOS:\nNome: ${lead.nome}\nEmpresa: ${lead.empresa}\nCargo: ${lead.cargo}\nSetor: ${perfil.setor}\nPorte: ${perfil.porte_estimado}\nMomento: ${perfil.momento_atual}\nTecnologias: ${(perfil.tecnologias_usadas || []).join(', ')}\nResumo: ${perfil.resumo_empresa}\n\nRetorne APENAS JSON:\n{\n  "score": <0-100>,\n  "classificacao": "<Frio|Morno|Quente|Hot>",\n  "justificativa": "<2 frases>",\n  "pontos_positivos": ["<até 3>"],\n  "pontos_negativos": ["<até 2>"]\n}`;

const bodyString = JSON.stringify({
  model: 'llama-3.3-70b-versatile',
  messages: [
    { role: 'system', content: 'Você é um especialista em qualificação de leads B2B. Retorne APENAS JSON válido.' },
    { role: 'user', content: promptScore }
  ],
  temperature: 0.2,
  max_tokens: 600
});

return {
  json: {
    lead,
    perfil,
    promptScore,
    bodyString
  }
};

const groqResponse = $input.item.json;
const scoreBruto = groqResponse.choices[0].message.content;
const { lead, perfil } = $('Monta Prompt — Agente Pontuador').item.json;

let scoreData = {};
try {
  const clean = scoreBruto.replace(/```json|```/g, '').trim();
  scoreData = JSON.parse(clean);
} catch(e) {
  scoreData = { score: 0, classificacao: 'Frio', justificativa: 'Erro ao processar score', pontos_positivos: [], pontos_negativos: [] };
}

const score = Number(scoreData.score) || 0;
const isHot = score >= 70;

const promptEmail = "Escreva um e-mail de prospecção personalizado.\n\nREGRAS:\n- Tom profissional mas próximo\n- Mencione algo específico sobre a empresa\n- Foque em 1 dor específica\n- Máximo 5 parágrafos curtos\n- CTA claro no final\n- Assunto separado por ---\n- Escreva em português brasileiro\n- Assine o e-mail com o nome \"Mikael Diehl\" e o cargo \"Consultor de TI\"\n- Use exatamente este link de agendamento: SEU_CALENDLY_LINK_AQUI\n\nDADOS:\nNome: " + lead.nome + "\nEmpresa: " + lead.empresa + "\nCargo: " + lead.cargo + "\nSetor: " + perfil.setor + "\nResumo: " + perfil.resumo_empresa + "\nMomento: " + perfil.momento_atual + "\nDores: " + (perfil.pontos_de_dor_possiveis || []).join(', ') + "\nPontos positivos: " + (scoreData.pontos_positivos || []).join(', ') + "\n\nRetorne:\nASSUNTO: <assunto>\n---\n<corpo do email>";

const bodyString = JSON.stringify({
  model: 'llama-3.3-70b-versatile',
  messages: [
    { role: 'system', content: 'Você é um especialista em copywriting B2B. Escreva e-mails de prospecção personalizados, humanos e eficazes.' },
    { role: 'user', content: promptEmail }
  ],
  temperature: 0.7,
  max_tokens: 800
});

return {
  json: {
    lead,
    perfil,
    scoreData,
    score,
    isHot,
    promptEmail,
    bodyString
  }
};

const groqResponse = $input.item.json;
const emailBruto = groqResponse.choices[0].message.content;
const { lead, perfil, scoreData, score, isHot } = $('Parse Score + Monta Prompt Email').item.json;

const partes = emailBruto.split('---');
let assunto = 'Oportunidade para ' + lead.empresa;
let corpoEmail = emailBruto;

if (partes.length >= 2) {
  assunto = partes[0].replace('ASSUNTO:', '').trim();
  corpoEmail = partes.slice(1).join('---').trim();
}

return {
  json: {
    lead,
    perfil,
    scoreData,
    score,
    isHot,
    assunto,
    corpoEmail
  }
};

