const { lead, perfil, scoreData, score, assunto, corpoEmail } = $('Parse E-mail Gerado').item.json;

return {
  json: {
    lead,
    perfil,
    scoreData,
    score,
    assunto,
    corpoEmail,
    nurturingSequencia: [
      { dia: 3, acao: 'Enviar conteúdo relevante do setor' },
      { dia: 7, acao: 'Convidar para webinar ou demo' },
      { dia: 14, acao: 'Follow-up com case de sucesso' },
      { dia: 30, acao: 'Requalificar ou arquivar' }
    ],
    statusCRM: 'nurturing'
  }
};

const dados = $('Parse E-mail Gerado').item.json;
const { lead, perfil, scoreData, score } = dados;

const registro = {
  timestamp: new Date().toISOString(),
  nome: lead.nome,
  email: lead.email,
  empresa: lead.empresa,
  cargo: lead.cargo,
  setor: perfil.setor,
  porte: perfil.porte_estimado,
  score: score,
  classificacao: scoreData.classificacao,
  justificativa: scoreData.justificativa,
  status: score >= 70 ? 'email_enviado' : 'nurturing',
  processado: true
};

return { json: registro };
